def isq(a):
    if a < 2:
        return a
    x = 1
    while x * x <= a:
        x = x * 2
    y = (x + a // x) // 2
    while y < x:
        x = y
        y = (x + a // x) // 2
    return x

def S(n):
    if n == 0:
        return 0
    m = isq(2 * n * n) - n
    return n * (n + 1) // 2 + n * m - m * (m + 1) // 2 - S(m)

def f(p):
    n = p['n']
    q = isq(n * n // 2)
    odd = S(n) - 2 * (n * q - S(q))
    return n - odd

def f(p):
    n = p['n']
    m = p['m']
    t = m // 2
    if n <= t:
        return (n * n) // m - 1 // m + 1
    if t == 0:
        return n
    return (t * t) // m - 1 // m + 1 + (n - t)

def win(h, last, memo):
    key = (tuple(h), last)
    if key in memo:
        return memo[key]
    res = False
    for i in range(len(h)):
        if i == last:
            continue
        for take in range(1, h[i] + 1):
            h[i] = h[i] - take
            w = win(h, i, memo)
            h[i] = h[i] + take
            if not w:
                res = True
                break
        if res:
            break
    memo[key] = res
    return res

def f(p):
    h = list(p['h'])
    memo = {}
    cnt = 0
    for i in range(len(h)):
        for take in range(1, h[i] + 1):
            h[i] = h[i] - take
            if not win(h, i, memo):
                cnt = cnt + 1
            h[i] = h[i] + take
    return cnt

def tdiv(a, b):
    q = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        return -q
    return q

def f(p):
