def f(p):
    n = p['n']
    lo = 0
    hi = 1
    while hi * (hi + 1) // 2 <= n:
        hi *= 2
    while hi - lo > 1:
        m = (lo + hi) // 2
        if m * (m + 1) // 2 <= n:
            lo = m
        else:
            hi = m
    return n - lo * (lo + 1) // 2

def f(p):
    a = p['a0']
    tails = []
    for i in range(p['n']):
        if i > 0:
            a = (a * p['A'] + p['C']) % p['M']
        lo = 0
        hi = len(tails)
        while lo < hi:
            m = (lo + hi) // 2
            if tails[m] <= a:
                lo = m + 1
            else:
                hi = m
        if lo == len(tails):
            tails.append(a)
        else:
            tails[lo] = a
    return len(tails)

def f(p):
    t = 0
    for k in range(1, p['N'] + 1):
        bits = []
        x = k
        while x > 0:
            bits.append(x % 2)
            x = x // 2
        for i in range(len(bits) - 2):
            if bits[i] == 1 and bits[i + 1] == 0 and bits[i + 2] == 1:
                t += 1
